TLM.f("Tempora/Pent11-4",{"officium":"Feria quinta infra Hebdomadam XI post Octavam Pentecostes","rule":["Oratio Dominica","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"ruleInherited":["Gloria","Credo","Prefatio=Trinitate","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"fallback":"Tempora/Pent11-0","from":{"Introitus":"Tempora/Pent11-0","Oratio":"Tempora/Pent11-0","Lectio":"Tempora/Pent11-0","Graduale":"Tempora/Pent11-0","Evangelium":"Tempora/Pent11-0","Offertorium":"Tempora/Pent11-0","Secreta":"Tempora/Pent11-0","Communio":"Tempora/Pent11-0","Postcommunio":"Tempora/Pent11-0"},"sections":{"Introitus":[{"k":"ref","la":"Ps 67:6-7; 67:36"},{"k":"text","la":"Deus in loco sancto suo: Deus qui inhabitáre facit unánimes in domo: ipse dabit virtútem et fortitúdinem plebi suæ."},{"k":"ref","la":"Ps 67:2"},{"k":"text","la":"Exsúrgat Deus, et dissipéntur inimíci ejus: et fúgiant, qui odérunt eum, a fácie ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Deus in loco sancto suo: Deus qui inhabitáre facit unánimes in domo: ipse dabit virtútem et fortitúdinem plebi suæ."}],"Oratio":[{"k":"text","la":"Omnípotens sempitérne Deus, qui, abundántia pietátis tuæ, et mérita súpplicum excédis et vota: effúnde super nos misericórdiam tuam; ut dimíttas quæ consciéntia métuit, et adícias quod orátio non præsúmit."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios."},{"k":"ref","la":"1 Cor 15:1-10"},{"k":"text","la":"Fratres: Notum vobis fácio Evangélium, quod prædicávi vobis, quod et accepístis, in quo et statis, per quod et salvámini: qua ratione prædicáverim vobis, si tenétis, nisi frustra credidístis. Trádidi enim vobis in primis, quod et accépi: quóniam Christus mortuus est pro peccátis nostris secúndum Scriptúras: et quia sepúltus est, et quia resurréxit tértia die secúndum Scriptúras: et quia visus est Cephæ, et post hoc úndecim. Deinde visus est plus quam quingéntis frátribus simul, ex quibus multi manent usque adhuc, quidam autem dormiérunt. Deinde visus est Jacóbo, deinde Apóstolis ómnibus: novíssime autem ómnium tamquam abortívo, visus est et mihi. Ego enim sum mínimus Apostolórum, qui non sum dignus vocári Apóstolus, quóniam persecútus sum Ecclésiam Dei. Grátia autem Dei sum id quod sum, et grátia ejus in me vácua non fuit."}],"Graduale":[{"k":"ref","la":"Ps 27:7 27:1"},{"k":"text","la":"In Deo sperávit cor meum, et adjútus sum: et reflóruit caro mea, et ex voluntáte mea confitébor illi."},{"k":"text","la":"Ad te, Dómine, clamávi: Deus meus, ne síleas, ne discédas a me. Allelúja, allelúja","mark":"V"},{"k":"ref","la":"Ps 80:2-3"},{"k":"text","la":"Exsultáte Deo, adjutóri nostro, jubiláte Deo Jacob: súmite psalmum jucúndum cum cíthara. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Marcum."},{"k":"ref","la":"Marc 7:31-37"},{"k":"text","la":"In illo témpore: Exiens Jesus de fínibus Tyri, venit per Sidónem ad mare Galilǽæ, inter médios fines Decapóleos. Et addúcunt ei surdum et mutum, et deprecabántur eum, ut impónat illi manum. Et apprehéndens eum de turba seórsum, misit dígitos suos in aurículas ejus: et éxspuens, tétigit linguam ejus: et suspíciens in cœlum, ingémuit, et ait illi: Ephphetha, quod est adaperíre. Et statim apértæ sunt aures ejus, et solútum est vínculum linguæ ejus, et loquebátur recte. Et præcépit illis, ne cui dícerent. Quanto autem eis præcipiébat, tanto magis plus prædicábant: et eo ámplius admirabántur, dicéntes: Bene ómnia fecit: et surdos fecit audíre et mutos loqui."}],"Offertorium":[{"k":"ref","la":"Ps 29:2-3"},{"k":"text","la":"Exaltábo te, Dómine, quóniam suscepísti me, nec delectásti inimícos meos super me: Dómine, clamávi ad te, et sanásti me."}],"Secreta":[{"k":"text","la":"Réspice, Dómine, quǽsumus, nostram propítius servitútem: ut, quod offérimus, sit tibi munus accéptum, et sit nostræ fragilitátis subsidium."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"rubric","la":"Prov 3:9-10"},{"k":"text","la":"Hónora Dóminum de tua substántia, et de prímitiis frugum tuárum: et implebúntur hórrea tua saturitáte, et vino torculária redundábunt."}],"Postcommunio":[{"k":"text","la":"Sentiámus, quǽsumus, Dómine, tui perceptióne sacraménti, subsídium mentis et córporis: ut, in utróque salváti, cæléstis remédii plenitúdine gloriémur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"84f518013d853262":{"t":"Ps 67, 6-7 i 36, Ps 67, 2\n(Ps 67, 6-7 i 36) Bog je u svojem svetom mjestu, Bog koji čini da jednodušni stanuju u kući dat će snagu i jakost svojemu puku. (Ps 67, 2) Neka ustane Bog i razaspu se njegovi neprijatelji! Neka bježe svi koji ga mrze od njegova lica.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 67, 6-7 i 36) Bog je u svojem svetom mjestu, Bog koji čini da jednodušni stanuju u kući dat će snagu i jakost svojemu puku.","kn":"(Ps. 67, 6, 36)-. Bog je u svetomu stanu 'svojem; Bog daje zapuštenima naselje, on će dati kre- ‘post i jakost puku -svojemu. (Ps. 67, 2) Nek ustane Bog i nek se razaspu neprijatelji njegovi, i meka pobjegnu od lica njegova, koji mrze na nj! Slava Ocu . . . Bog je ... '","knRef":"Kniewald 1942, str. 392–393 (snimka 197) (OCR)"},"1ec347189239b472":{"t":"<i>Pomolimo se</i>.\nSvemogući vječni Bože, koji obiljem svoje dobrote nadilaziš i zasluge i molitve onih koji ti se mole, izlij na nas svoje milosrđe te oprosti ono što tišti savjest, a dodaj i ono što se ne usuđujemo moliti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Svemogući, vječni Bože,' koji obiljem milostivosti svoje nadvisuješ i zasluge i želje molbenika: izlij na nas milost svoju, da oprostiš, od čega se savjest boji i dodaš, što še ne usuđujemo moliti, po G. n. ■","knRef":"Kniewald 1942, str. 392–393 (snimka 197) (OCR)"},"4af2381d951ce3af":{"t":"1 Kor 15, 1-10\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo, podsjećam vas na Evanđelje koje sam vam propovijedao i koje ste vi spremno primili i u kojem ste dosada postojani. Po njemu ćete se spasiti, ako živite onako kao što sam vam propovijedao, osim da ste povjerovali lakomisleno. A predao sam vam prije svega ono što sam i primio: Da je, prema Pismima, Krist umro za naše grijehe; da su ga, jednako prema Pismima, pokopali i da je treći dan uskrsnuo; da se je ukazao najprije Kefi i onda jedanaestorici. Poslije toga ukazao se braći, kojih je bilo zajedno više od pet stotina, od kojih su neki usnuli, a mnogi žive još i danas. Potom se ukazao Jakovu, pa svim apostolima. Naposlije ukazao se i meni, nedonoščetu. Uistinu ja sam najmanji među apostolima a nisam ni dostojan zvati se apostolom, jer sam progonio Crkvu Božju. Ali Božjom milošću jesam što jesam i njegova milost nije u meni besplodna.","kn":"Čitanje poslanice hl. Pavla apostola Korinćanima (I, 15. 1-10). Braćo! Dozivljem vam u pamet evan- đelje, koje sam vam propovijedao, koje ste i primili, u kojem ste i postojani, po kojem ćete se i spasiti, ako držite, kako sam vam propovijedao, osim ako ste uzalud vjerovali! A predao sam vam najprije ono, što sam i primio, da je Krist umro za naše grijehe, prema Pismima. I da se javio Kefi i zatim jedanaestorici. Iza toga vidjelo ga je zajedno više od pet stotina braće, od kojih mnogi još žive i danas, a neki su usnuli. Javio se zatim Jakovu, onda svim apostolima, a poslije, svih javio se i meni, kao nedonoščetu. Jer među apostolima najmanji sam ja, koji nijesam dostojan da se zovem apostolom, jer sam progonio Božju crkvu. Ali Božjom milošću jesam. Sto jesam, i njegova milost nije bila u meni bez ploda. ‘","knRef":"Kniewald 1942, str. 392–393 (snimka 197) (OCR)"},"19fcc164613e5b93":{"t":"Ps 27, 7 i 1\nU Boga se pouzdalo moje srce i pomogao mi je. I pomladilo se moje tijelo, zato ću ga rado slaviti. Vapijem, Gospodine, k tebi. Bože moj, nemoj mi se oglušiti.\n\nPs 80, 2-3\n<i>Aleluja</i>, <i>aleluja</i>.\nKličite Bogu našemu pomoćniku! Veličajte Boga Jakovljeva! Uzmite milozvučnu citaru s harfom. <i>Aleluja</i>.","kn":"(Ps. 27, 7, 1). U Boga se uzda srce moje i pomože mi; i procvjeta tijelo moje i od volje svoje slavit ću ga. K Tebi, Gospodine, vapih. Bože moj, nemoj šutjeti, ne odstupi od mene.\n\nAleluja, aleluja. (Ps. 80, 7, 1) Radujte, se Bogu, pomoćniku našemu, kličite Bogu Jakovljevu, počnite ugodnu pjesmu uz kitaru. Aleluja.","knRef":"Kniewald 1942, str. 392–393 (snimka 197) (OCR)"},"323879891e1c408f":{"t":"Mk 7, 31-37\nSlijedi sveto Evanđelje po Marku. U ono vrijeme uputi se Isus iz predjela oko Tira te preko Sidona dođe do Galilejskoga mora, posred Deseterogradskih krajeva. I dovedu k njemu gluha i nijema čovjeka i zamole ga da stavi na njega ruku. On ga uze nasamo od naroda, metnu svoj prst u njegove uši, pljunu, dotakne se njegova jezika, pogleda u nebo, uzdahne i reče mu: Efeta! to jest: Otvori se! I odmah mu se otvore uši i odriješi sapeti jezik i progovori pravilno. I zabrani im da to nikome ne kazuju. Ali, što im je on više zabranjivao, oni su sve više pripovijedali. I sve se više divili i govorili: Sve je dobro učinio! I gluhima je vratio sluh, a nijemima govor.","kn":"t Slijedi sveto evanđelje po Marku (7, 31-37). U ono vrijeme kada .je Isus izašao iz krajeva Tlrskih,' dođe preko Siđena do Galilejskoga mora usred Desetogradskih. krajeva. I dovedu mu gluhonijemoga i zamole ga, da metne na nj ruku. I uze ga nasamo od naroda, dbtače svojim prstom njegove uši, pijunu i dotaknu se njegova jezika i pogleda na nebo, uzdahnu i reče mu; Efeta! Sto znači; Otvori se! I odmah mu se otvoriše uši i odriješi mu se sapeti jezik i progovori pravo. I zabrani im ikomu govoriti. Ali kolikogod im je on više bra- nio, oai su sve više propovijedali i sve više diveći se govorili: Sve je učinio dobro, gluhima je povratio siuh, a nijemima govor. .","knRef":"Kniewald 1942, str. 392–393 (snimka 197) (OCR)"},"303da7d32e6bd744":{"t":"Ps 29, 2-3\nSlavit ću te, Gospodine, jer si me uzeo k sebi. Nisi dao da neprijatelj slavi pobjedu nada mnom. Gospodine, zavapio sam k tebi i ozdravio si me.","kn":"(Ps. 29, 2-3). Slavim Te, Gospodine, jer si me očuvao i nisi dao neprijateljima mojim da se vesele nada mnom. Gospodine, k Tehi sam vapio i iscijel'io si me.","knRef":"Kniewald 1942, str. 100–101 (snimka 51) (OCR)"},"4094f2de6b7f0f28":{"t":"Pogledaj, molimo, Gospodine, milostivo našu službu, da ono što ti prinosimo bude tebi mio dar, a našoj slabosti pomoć.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Obazri se. Gospodine, molimo, milostivo na našu službu, što je prinosimo, da Tebi bude ugodan dar, a našoj nejrakosti pomoć, po G. n.","knRef":"Kniewald 1942, str. 394–395 (snimka 198) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"872a67018312f621":{"t":"Izr 3, 9-10\nDaj čast Gospodinu od svojega posjeda i od prvina svojih plodova. I tvoje će se žitnice napuniti obilja, a vino će se prelijevati iz tvojih sudova.","kn":", (Prov. 3, 9). Časti Gospodina od imetka svojega i od prvina plodova svojih i napunit će se žitnice tvoje do sita i vinom će se točila prelijevati.","knRef":"Kniewald 1942, str. 394–395 (snimka 198) (OCR)"},"f1e926b6a6b2016f":{"t":"<i>Pomolimo se</i>.\nMolimo, Gospodine, da po primanju tvoga otajstva osjetimo pomoć duši i tijelu, te se ozdravljeni možemo radovati što smo primili puninu nebeskoga lijeka.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Gospodine, da primanjem Tvoje tajne nađemo pomoć duši i tijelu, te se spašeni u jednom i drugom hvalimo puninom nebeske pomoći, po G. n.","knRef":"Kniewald 1942, str. 394–395 (snimka 198) (OCR)"}}});
